/**
 * Returns the icon for a technology by its Name (case-insensitive),
 * or undefined if there is no matching brand icon (caller should
 * fall back to the colored-dot design in that case).
 */
export function getTechIcon(name: string): TechIcon | undefined {
  return techIcons[name.toLowerCase()];
}
